// Punto único donde se decide a qué chat de Telegram va cada aviso.
// Es la razón de ser de este subflujo: hoy, mandar los avisos 'critico' a un
// chat distinto del operativo exige tocar cada nodo Telegram uno por uno; con
// este subflujo alcanza con cambiar esta pieza para que todos los llamadores
// que declaren nivel:'critico' se beneficien sin que el flujo principal sepa
// nada de esta decisión.
const entrada = $input.first().json;
const nivel = entrada.nivel || 'info';
const chatId = nivel === 'critico'
  ? ($env.TELEGRAM_CHAT_ID_CRITICO || $env.TELEGRAM_CHAT_ID)
  : $env.TELEGRAM_CHAT_ID;

return [{ json: { mensaje: entrada.mensaje, nivel, chatId } }];
